<?php
declare(strict_types=1);
namespace Hostider\OfflineBackup;
use Hostider\Core\Database\Database;
final class Rehearsal
{
 private static function notify(?\Closure $hook,string $stage,mixed $value=null):void{if($hook!==null){$hook($stage,$value);}}
 private static function publicResult(string $status,array $image,array $finance,string $cipher):array{return ['status'=>$status,'classification'=>'SYNTHETIC','format'=>1,'tables'=>count($image['tables']),'rows'=>$image['manifest']['rows'],'files'=>count($image['files']),'manifest_sha256'=>Guard::hash($image['manifest']),'cipher_sha256'=>$cipher,'finance'=>$finance,'cutover_allowed'=>false,'effects_allowed'=>false,'real_gate_status'=>'BLOCKED','production_backup_restore'=>'NOT_VERIFIED','pitr_rpo'=>'NOT_VERIFIED'];}
 public static function backup(Workspace $w,#[\SensitiveParameter] string $key,?\Closure $hook=null):array{$lock=$w->lock();$db=null;$locked=false;$out=null;$reserved=false;$part=$w->root.'/backup.partial';$dest=$w->root.'/backup.bin';try{Guard::require(strlen($key)===32&&$w->state()['backup']==='NONE'&&!file_exists($part)&&!is_link($part)&&!file_exists($dest)&&!is_link($dest),'BACKUP_NO_OVERWRITE');Guard::space($w->root);Guard::databaseSpace($w->admin);$sealed=$w->frozen();$model=$w->model();$db=$w->db();$model->assertSchema($db);$w->set('backup','WRITING');$reserved=true;self::notify($hook,'before_lock');$model->lock($db);$locked=true;self::notify($hook,'locked');$data=$model->snapshot($db);$catalog=ManagedFiles::catalog(ManagedFiles::decoded($data));$observed=ManagedFiles::inspect($w,$catalog);Guard::require(Guard::hash($observed)===Guard::hash($sealed),'SEAL_CHANGED');$out=Guard::open($part,'x+b');$writer=StreamArchive::writer($out,$key);$image=new Image();$emit=function(array $frame,bool $final=false)use($writer,$image):void{$writer->push($frame,$final);$image->accept($frame,$final);};$emit(['kind'=>'header','contract'=>StreamArchive::CONTEXT,'format'=>1,'classification'=>'SYNTHETIC','operation_id'=>$w->id,'binding'=>$w->binding(),'created_at'=>gmdate('Y-m-d\TH:i:s\Z'),'database_version'=>(string)$db->execute('SELECT VERSION()')->fetchColumn(),'schema_fingerprint'=>$model->fingerprint(),'migrations'=>$model->migration,'triggers'=>$model->triggers,'snapshot_model'=>'NATIVE_TABLE_READ_LOCKS_AND_POSIX_SEALED_FILES']);foreach($data['tables'] as $n=>$rows){$emit(['kind'=>'table','name'=>$n,...$data['metadata'][$n]]);foreach($rows as $i=>$row){$emit(['kind'=>'row','table'=>$n,'index'=>$i,'values'=>$row,'sha256'=>Guard::hash($row)]);self::notify($hook,'export_row',$n);}}foreach($catalog as $k=>$meta){$b=ManagedFiles::bytes($w,$meta);$emit(['kind'=>'file','key'=>$k,'meta'=>$meta,...$observed[$k]]);for($i=0,$index=0;$i<strlen($b);$i+=32768,++$index){$emit(['kind'=>'chunk','key'=>$k,'index'=>$index,'data'=>base64_encode(substr($b,$i,32768))]);}self::notify($hook,'export_file',$k);}self::notify($hook,'before_manifest');Guard::require(Guard::hash(ManagedFiles::inspect($w,$catalog))===Guard::hash($sealed)&&Guard::hash($w->frozen())===Guard::hash($sealed),'SOURCE_CHANGED');$model->assertSchema($db);$emit(['kind'=>'manifest','content'=>$image->computed()],true);Guard::require(fflush($out)&&fsync($out),'ARCHIVE_SYNC');fclose($out);$out=null;self::notify($hook,'before_publish');$w->fence();Guard::require(Guard::hash(ManagedFiles::inspect($w,$catalog))===Guard::hash($sealed),'FINAL_FILES_CHANGED');$verify=Guard::open($part);try{$checked=new Image();$cipher=StreamArchive::scan($verify,$key,$checked->accept(...));$v=$checked->result();Guard::require(Guard::hash($v['manifest'])===Guard::hash($image->result()['manifest']),'WRITE_READBACK');$result=self::publicResult('OFFLINE_ENCRYPTED_BACKUP_COMPLETE',$v,$model->validate($v),$cipher);}finally{fclose($verify);}Guard::require(hash_file('sha256',$part)===$cipher,'CIPHER_CHANGED');Guard::require(!file_exists($dest)&&!is_link($dest)&&rename($part,$dest),'ARCHIVE_PUBLISH');Guard::syncDir($w->root);$w->set('backup','COMPLETE');return $result;}catch(\Throwable $e){if(is_resource($out)){fclose($out);}if($reserved){if(file_exists($part)&&!is_link($part)){Guard::file($part);Guard::require(unlink($part),'FAILED_CIPHER_CLEAN');}$w->set('backup','FAILED');}throw $e;}finally{if($locked){$db->execute('UNLOCK TABLES');}fclose($lock);}}
 public static function restore(Workspace $w,#[\SensitiveParameter] string $key,?\Closure $hook=null):array{$lock=$w->lock();$file=null;$sinkFile=null;$staged=[];$reserved=false;try{Guard::require($w->state()['backup']==='COMPLETE'&&$w->state()['target']===null&&$w->state()['target_state']==='NONE'&&!file_exists($w->root.'/restored')&&!is_link($w->root.'/restored'),'RESTORE_NO_REPLAY_OR_OVERWRITE');Guard::space($w->root);$file=Guard::open($w->root.'/backup.bin');Guard::require(flock($file,LOCK_SH|LOCK_NB),'ARCHIVE_BUSY');$first=new Image();$cipher=StreamArchive::scan($file,$key,$first->accept(...));$image=$first->result();Guard::require($image['header']['operation_id']===$w->id&&$image['header']['binding']===$w->binding()&&$image['header']['database_version']===(string)$w->admin->execute('SELECT VERSION()')->fetchColumn(),'SOURCE_BINDING_OR_DB_VERSION');Guard::databaseSpace($w->admin);$model=$w->model();$finance=$model->validate($image);$catalog=ManagedFiles::catalog(ManagedFiles::decoded($image));Guard::require(array_keys($catalog)===array_keys($image['files']),'FILE_CATALOG');foreach($catalog as $k=>$meta){Guard::require(Guard::hash($meta)===Guard::hash($image['files'][$k]['meta']),'FILE_REFERENCE');}self::notify($hook,'authenticated');$w->fence();Guard::space($w->root);$reserved=true;$target=$w->newTarget();self::notify($hook,'target_created');$model->import($w,$image,$hook);self::notify($hook,'database_restored');$w->restoredDirectory();$sink=function(string $stage,string $k,array $v)use($w,$catalog,&$sinkFile,&$staged,$hook):void{if($stage==='start'){Guard::require(isset($catalog[$k]),'RESTORE_FILE_SCOPE');$m=$catalog[$k];$path=$w->fileRoot($m['group'],true).'/.stage-'.$m['id'];$sinkFile=Guard::open($path,'x+b');Guard::require(unlink($path)&&fstat($sinkFile)['nlink']===0,'ANONYMOUS_STAGE');$staged[$k]=$sinkFile;}elseif($stage==='chunk'){Guard::write($sinkFile,$v['bytes']);self::notify($hook,'restore_file_chunk',$k);}else{Guard::require(is_resource($sinkFile)&&fflush($sinkFile)&&fsync($sinkFile),'RESTORE_FILE_SYNC');$sinkFile=null;}};$second=new Image($sink);$again=StreamArchive::scan($file,$key,$second->accept(...));Guard::require(hash_equals($cipher,$again)&&Guard::hash($second->result()['manifest'])===Guard::hash($image['manifest']),'ARCHIVE_CHANGED_BETWEEN_PASSES');$model->lock($target);try{$observed=$model->snapshot($target);Guard::require(Guard::hash($observed['tables'])===Guard::hash($image['tables']),'RESTORED_ROW_INTEGRITY');foreach($image['metadata'] as $n=>$v){Guard::require($observed['metadata'][$n]['schema']===$v['schema'],'RESTORED_SCHEMA_COUNTER');}self::notify($hook,'restore_before_materialize');foreach($staged as $k=>$handle){$m=$catalog[$k];Guard::require(rewind($handle),'STAGE_SEEK');$out=Guard::open($w->fileRoot($m['group'],true).'/'.$m['name'],'x+b');try{while(!feof($handle)){$chunk=fread($handle,32768);Guard::require(is_string($chunk),'STAGE_READ');Guard::write($out,$chunk);}Guard::require(fflush($out)&&fsync($out),'PUBLISH_FILE_SYNC');}finally{fclose($out);}fclose($handle);unset($staged[$k]);self::notify($hook,'restore_materialized_file',$k);}$actual=ManagedFiles::inspect($w,$catalog,true,false);foreach($image['files'] as $k=>$f){Guard::require($actual[$k]['sha256']===$f['sha256']&&$actual[$k]['bytes']===$f['bytes'],'RESTORED_FILE_INTEGRITY');}foreach(['attachments','documents'] as $g){Guard::syncDir($w->fileRoot($g,true));}Guard::syncDir($w->root.'/restored');self::notify($hook,'restore_verified');$w->fence();$result=self::publicResult('ISOLATED_RESTORE_REHEARSAL_COMPLETE',$image,$finance,$cipher);$w->set('target_state','COMPLETE');return $result;}finally{$target->execute('UNLOCK TABLES');}}catch(\Throwable $e){foreach($staged as $handle){if(is_resource($handle)){fclose($handle);}}$staged=[];$sinkFile=null;if($reserved){try{$w->abortTarget();}catch(\Throwable){$w->set('target_state','FAILED');}}throw $e;}finally{foreach($staged as $handle){if(is_resource($handle)){fclose($handle);}}if(is_resource($file)){fclose($file);}fclose($lock);}}
 public static function verify(Workspace $w,#[\SensitiveParameter] string $key):array{$lock=$w->lock();$file=null;$db=null;$locked=false;try{Guard::require($w->state()['backup']==='COMPLETE'&&$w->state()['target_state']==='COMPLETE','VERIFY_COMPLETE_REQUIRED');$file=Guard::open($w->root.'/backup.bin');Guard::require(flock($file,LOCK_SH|LOCK_NB),'ARCHIVE_BUSY');$reader=new Image();$cipher=StreamArchive::scan($file,$key,$reader->accept(...));$image=$reader->result();Guard::require($image['header']['operation_id']===$w->id&&$image['header']['binding']===$w->binding()&&$image['header']['database_version']===(string)$w->admin->execute('SELECT VERSION()')->fetchColumn(),'SOURCE_BINDING_OR_DB_VERSION');$model=$w->model();$finance=$model->validate($image);$db=$w->db('target');$model->lock($db);$locked=true;$actual=$model->snapshot($db);Guard::require(Guard::hash($actual['tables'])===Guard::hash($image['tables']),'RESTORED_ROW_INTEGRITY');foreach($image['metadata'] as $n=>$v){Guard::require($actual['metadata'][$n]['schema']===$v['schema'],'RESTORED_SCHEMA_COUNTER');}$catalog=ManagedFiles::catalog(ManagedFiles::decoded($image));$files=ManagedFiles::inspect($w,$catalog,true,false);Guard::require(array_keys($catalog)===array_keys($image['files']),'FILE_CATALOG');foreach($image['files'] as $n=>$v){Guard::require($files[$n]['sha256']===$v['sha256']&&$files[$n]['bytes']===$v['bytes']&&Guard::hash($catalog[$n])===Guard::hash($v['meta']),'RESTORED_FILE_INTEGRITY');}$w->fence();return self::publicResult('RESTORED_TARGET_VERIFIED_READ_ONLY',$image,$finance,$cipher);}finally{if($locked){$db->execute('UNLOCK TABLES');}if(is_resource($file)){fclose($file);}fclose($lock);}}

}
